<?php require_once '../includes/functions.php';require_staff();$pdo=db();$where='';$params=[];if(user()['role']==='teacher'){$where=' WHERE created_by=?';$params[] = user()['id'];}
$s=$pdo->prepare("SELECT COUNT(*) FROM quizzes$where");$s->execute($params);$quizCount=$s->fetchColumn();$studentCount=$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn();$attemptCount=$pdo->query('SELECT COUNT(*) FROM attempts')->fetchColumn();
$sql="SELECT q.id,q.title,q.is_published,q.created_at,c.name category,u.name creator,(SELECT COUNT(*) FROM questions WHERE quiz_id=q.id) questions FROM quizzes q JOIN categories c ON c.id=q.category_id JOIN users u ON u.id=q.created_by".($where?' WHERE q.created_by=?':'').' ORDER BY q.created_at DESC LIMIT 8';$s=$pdo->prepare($sql);$s->execute($params);$quizzes=$s->fetchAll();$pageTitle='Admin Dashboard';require '../includes/header.php';?>
<h1><?=user()['role']==='admin'?'Admin':'Teacher'?> Dashboard</h1><div class="actions"><a class="button" href="quizzes.php">Manage Quizzes</a><a class="button secondary" href="ai_generate.php">AI Generate Quiz</a><a class="button secondary" href="students.php">Students & Results</a></div><div class="grid"><div class="card"><span class="muted">Quizzes</span><div class="stats"><?=$quizCount?></div></div><div class="card"><span class="muted">Students</span><div class="stats"><?=$studentCount?></div></div><div class="card"><span class="muted">Attempts</span><div class="stats"><?=$attemptCount?></div></div></div>
<h2>Recent Quizzes</h2><div class="table-wrap"><table><tr><th>Title</th><th>Category</th><th>Questions</th><th>Status</th></tr><?php foreach($quizzes as $q):?><tr><td><a href="questions.php?quiz_id=<?=$q['id']?>"><?=e($q['title'])?></a></td><td><?=e($q['category'])?></td><td><?=$q['questions']?></td><td><?=$q['is_published']?'Published':'Draft'?></td></tr><?php endforeach;?></table></div>
<?php require '../includes/footer.php';?>
